const fs=require('fs'); const zlib=require('zlib');
const root='C:/project/damage_web_dev/.agents/artifacts/hero23-cursor-entry-20260909';
const binding=JSON.parse(fs.readFileSync(root+'/来源绑定与当前文本.json','utf8'));
function load(p){return JSON.parse(zlib.gunzipSync(fs.readFileSync(p)).toString('utf8'));}
const clients={Amumu:load(root+'/参考资料/客户端原文/Amumu.json.gz'), Zac:load(root+'/参考资料/客户端原文/Zac.json.gz')};
const diffs=[];
for (const hero of binding.heroes) {
  const client=clients[hero.id];
  for (const skill of hero.skills) {
    const c=client[skill.binding];
    const b=skill.object;
    if (!c) { diffs.push(hero.id+' '+skill.slot+' MISSING in gz'); continue; }
    const cs=JSON.stringify(c.mSpell?.mSpellCalculations||null);
    const bs=JSON.stringify(b.mSpell?.mSpellCalculations||null);
    const cd=JSON.stringify(c.mSpell?.DataValues||null);
    const bd=JSON.stringify(b.mSpell?.DataValues||null);
    if (cs!==bs) diffs.push(hero.id+' '+skill.slot+' calculations differ');
    if (cd!==bd) diffs.push(hero.id+' '+skill.slot+' DataValues differ');
    const fields=['mCastTime','spellCastTime','spellTotalTime','mCoefficient'];
    for (const f of fields) {
      if (JSON.stringify(c.mSpell?.[f])!==JSON.stringify(b.mSpell?.[f])) diffs.push(hero.id+' '+skill.slot+' '+f+' bind='+JSON.stringify(b.mSpell?.[f])+' gz='+JSON.stringify(c.mSpell?.[f]));
    }
  }
}
console.log(diffs.length?diffs.join('\n'):'roots match calculations/DataValues/cast fields');
// extra: Amumu W mCastTime, Q mCastTime
const w=clients.Amumu['Characters/Amumu/Spells/AuraofDespairAbility/AuraofDespair'].mSpell;
